"""Small standard-library TOML adapter used by the CLI implementation."""
from __future__ import annotations

import json
import math
try:
    import tomllib
except ImportError:  # Python 3.10
    tomllib = None
from typing import Any


def parse_toml(text: str) -> Any:
    if tomllib is not None:
        return tomllib.loads(text)
    # A deliberately small fallback for the basic TOML used by CLI inputs.
    root: dict[str, Any] = {}
    cur = root
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line.startswith("#"): continue
        if line.startswith("[") and line.endswith("]"):
            cur = root
            for part in line[1:-1].split("."):
                part = part.strip().strip('"\'')
                cur = cur.setdefault(part, {})
            continue
        if "=" not in line: continue
        k, v = line.split("=", 1); k = k.strip().strip('"\''); v = v.strip()
        try: val = json.loads(v)
        except Exception:
            if v.startswith("'") and v.endswith("'"): val = v[1:-1]
            elif v.lower() in ("true", "false"): val = v.lower() == "true"
            elif v.startswith("[") and v.endswith("]"):
                val = [p.strip().strip('"\'') for p in v[1:-1].split(",") if p.strip()]
            else:
                try: val = int(v)
                except ValueError:
                    try: val = float(v)
                    except ValueError: val = v
        cur[k] = val
    return root


def _key(s: str) -> str:
    if s and all(c.isalnum() or c in "_-" for c in s) and not s[0].isdigit():
        return s
    return json.dumps(s, ensure_ascii=False)


def _value(v: Any) -> str:
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, str):
        if "'" not in v and "\n" not in v and "\r" not in v:
            return "'" + v + "'"
        return json.dumps(v, ensure_ascii=False)
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        if math.isnan(v): return "nan"
        if math.isinf(v): return "inf" if v > 0 else "-inf"
        return repr(v)
    if isinstance(v, (list, tuple)):
        return "[" + ", ".join(_value(x) for x in v) + "]"
    if isinstance(v, dict):
        return "{ " + ", ".join(_key(str(k)) + " = " + _value(x) for k, x in v.items()) + " }"
    if v is None:
        # TOML has no null; keep output syntactically representable as a string.
        return "'null'"
    return _value(str(v))


def dump_toml(value: Any, compact: bool = False) -> str:
    """Serialize a data tree as TOML, using tables for nested mappings."""
    if not isinstance(value, dict):
        if isinstance(value, list) and all(isinstance(x, dict) for x in value):
            value = {"items": value}
        else:
            return "value = " + _value(value) + "\n"
    chunks: list[str] = []

    def emit(table: dict, path: list[str], array_item: bool = False) -> None:
        if path:
            chunks.append(("[[" if array_item else "[") + ".".join(_key(x) for x in path) + ("]]" if array_item else "]"))
        # Scalars, arrays of scalars, and inline maps first.
        children = []
        for k, v in sorted(table.items(), key=lambda pair: str(pair[0])):
            if isinstance(v, dict):
                children.append((str(k), v, False))
            elif isinstance(v, list) and v and all(isinstance(x, dict) for x in v):
                children.append((str(k), v, True))
            else:
                chunks.append(_key(str(k)) + " = " + _value(v))
        for k, child, is_array in children:
            if chunks and chunks[-1] != "": chunks.append("")
            if is_array:
                for item in child:
                    emit(item, path + [k], True)
            else:
                emit(child, path + [k])

    emit(value, [])
    return "\n".join(chunks).rstrip() + "\n"
