"""JSON output helpers matching Dasel's default JSON presentation."""
import json


def _normalize(value):
    # Go's JSON writer renders whole-valued floating point numbers without a
    # decimal suffix (for example 1.0 becomes 1).
    if isinstance(value, float) and value.is_integer():
        return int(value)
    if isinstance(value, list):
        return [_normalize(item) for item in value]
    if isinstance(value, dict):
        return {key: _normalize(item) for key, item in value.items()}
    return value


def dumps(value, compact=False):
    """Serialize a Python value using Dasel's indentation and newline rules."""
    value = _normalize(value)
    if compact:
        result = json.dumps(value, ensure_ascii=False, separators=(",", ":"), allow_nan=False)
    else:
        result = json.dumps(value, ensure_ascii=False, indent=4, allow_nan=False)
    # Go's JSON encoder escapes HTML-sensitive characters and line separators.
    return (result.replace('&', r'\u0026').replace('<', r'\u003c')
            .replace('>', r'\u003e').replace('\u2028', r'\u2028')
            .replace('\u2029', r'\u2029'))


def write(value, compact=False, stream=None):
    import sys
    (stream or sys.stdout).write(dumps(value, compact) + "\n")

